android.extraProguardRules:
# NoParchi R8 keeps.
# Broad on purpose: React Native, Expo modules and the codegen'd Turbo
# Modules are all resolved reflectively by name at runtime, so R8 cannot see
# the reference and will happily strip a class the bridge is about to ask for.
# The saving that matters here comes from dropping whole unused libraries and
# resources, not from shaving these packages.
-keep class com.noparchi.app.** { *; }
-keep class com.facebook.react.** { *; }
-keep class com.facebook.jni.** { *; }
-keep class com.facebook.hermes.** { *; }
-keep class expo.modules.** { *; }
-keep class com.swmansion.reanimated.** { *; }
-keep class com.swmansion.rnscreens.** { *; }
-keep class com.horcrux.svg.** { *; }
# ML Kit loads its barcode models through a registrar it looks up by name.
-keep class com.google.mlkit.** { *; }
-keep class com.google.android.gms.internal.mlkit_vision_barcode.** { *; }
-keepclassmembers class * { @com.facebook.proguard.annotations.DoNotStrip *; }
-keepclassmembers class * { @com.facebook.common.internal.DoNotStrip *; }
-keepclassmembers class * { native <methods>; }
-dontwarn com.facebook.react.**
-dontwarn expo.modules.**
-dontwarn okhttp3.**
-dontwarn okio.**
